class Solution {
    public int maxSumMinProduct(int[] nums){
        int n=nums.length;
        long[] prefix=new long[n+1];
        for(int i=0;i<n;i++)prefix[i+1]=prefix[i]+nums[i];
        int[] left=new int[n],right=new int[n];
        Deque<Integer> stack=new ArrayDeque<>();
        for(int i=0;i<n;i++){
            while(!stack.isEmpty()&&nums[stack.peekLast()]>=nums[i])stack.pollLast();
            left[i]=stack.isEmpty()?-1:stack.peekLast();
            stack.offerLast(i);
        }
        stack.clear();
        for(int i=n-1;i>=0;i--){
            while(!stack.isEmpty()&&nums[stack.peekLast()]>=nums[i])stack.pollLast();
            right[i]=stack.isEmpty()?n:stack.peekLast();
            stack.offerLast(i);
        }
        long best=0;
        for(int i=0;i<n;i++)best=Math.max(best,(prefix[right[i]]-prefix[left[i]+1])*nums[i]);
        return (int)(best%1_000_000_007);
    }
}

